arguments.content:
{ config, lib, pkgs, ... }:

let
  dnsdist = pkgs.dnsdist;
  recursor = pkgs.pdns-recursor;
  nsd = pkgs.nsd;

  recControl = "/run/current-system/sw/bin/rec_control";
in
{
  ###########################################################################
  # Identity
  ###########################################################################

  networking.hostName = "node23";
  networking.hosts."127.0.0.1" = [ "node23.n23.test" ];

  # The resolver is the local dnsdist listener; DHCP must not replace it.
  networking.nameservers = [ "127.0.0.1" ];
  networking.search = [ "n23.test" ];
  networking.dhcpcd.extraConfig = "nohook resolv.conf";

  time.timeZone = "Etc/UTC";
  i18n.defaultLocale = "C.UTF-8";

  # Ports served to clients: DNS over UDP/TCP, DNS over TLS, and SSH.
  networking.firewall = {
    enable = true;
    allowedTCPPorts = [ 22 53 853 ];
    allowedUDPPorts = [ 53 ];
  };

  boot.kernel.sysctl = {
    "net.core.rmem_max" = 8388608;
    "net.core.wmem_max" = 8388608;
    "net.ipv4.ip_local_port_range" = "10240 65535";
  };

  ###########################################################################
  # Accounts (names, UIDs/GIDs and home layout as provisioned)
  ###########################################################################

  users.groups = {
    admin = { gid = 117; };
    sudo = { gid = 27; };
    birch = { gid = 1301; };
    cedar = { gid = 1302; };
    nsd = { gid = 120; };
    pdns = { gid = 121; };
    _dnsdist = { gid = 122; };
  };

  users.users = {
    birch = {
      isNormalUser = true;
      uid = 1301;
      group = "birch";
      home = "/home/birch";
      homeMode = "750";
      createHome = true;
      description = "";
      shell = "/bin/bash";
      hashedPassword = "!";
    };

    cedar = {
      isNormalUser = true;
      uid = 1302;
      group = "cedar";
      home = "/home/cedar";
      homeMode = "750";
      createHome = true;
      description = "";
      shell = "/bin/bash";
      hashedPassword = "!";
    };

    nsd = {
      isSystemUser = true;
      uid = 112;
      group = "nsd";
      home = "/var/lib/nsd";
      createHome = false;
    };

    pdns = {
      isSystemUser = true;
      uid = 113;
      group = "pdns";
      description = "PowerDNS,,,";
      home = "/var/spool/powerdns";
      createHome = false;
    };

    _dnsdist = {
      isSystemUser = true;
      uid = 114;
      group = "_dnsdist";
      home = "/nonexistent";
      createHome = false;
    };
  };

  # /bin/bash is the login shell the provisioned accounts point at.
  systemd.tmpfiles.rules = [
    "L+ /bin/bash - - - - ${pkgs.bashInteractive}/bin/bash"
    "L+ /usr/bin/rec_control - - - - ${recursor}/bin/rec_control"
    "d /var/lib/nsd 0755 nsd nsd -"
    "d /var/spool/powerdns 0750 pdns pdns -"
    "d /etc/nsd/zones 0750 root nsd -"
    "d /etc/nsd/nsd.conf.d 0755 root root -"
  ];

  # Operators: birch may wipe and inspect the recursor cache; cedar may inspect it.
  security.sudo.extraRules = [
    {
      users = [ "birch" ];
      runAs = "root";
      commands = [
        { command = "${recControl} wipe-cache *"; options = [ "NOPASSWD" ]; }
        { command = "${recControl} get *"; options = [ "NOPASSWD" ]; }
        { command = "/usr/bin/rec_control wipe-cache *"; options = [ "NOPASSWD" ]; }
        { command = "/usr/bin/rec_control get *"; options = [ "NOPASSWD" ]; }
      ];
    }
    {
      users = [ "cedar" ];
      runAs = "root";
      commands = [
        { command = "${recControl} get *"; options = [ "NOPASSWD" ]; }
        { command = "/usr/bin/rec_control get *"; options = [ "NOPASSWD" ]; }
      ];
    }
    {
      groups = [ "sudo" "admin" ];
      runAs = "ALL:ALL";
      commands = [ { command = "ALL"; options = [ ]; } ];
    }
  ];

  security.sudo.extraConfig = ''
    Defaults	mail_badpass
  '';

  ###########################################################################
  # SSH
  ###########################################################################

  services.openssh = {
    enable = true;
    settings = {
      PermitRootLogin = "prohibit-password";
      PasswordAuthentication = false;
      KbdInteractiveAuthentication = false;
      X11Forwarding = true;
      PrintMotd = false;
    };
    hostKeys = [
      { type = "ed25519"; path = "/etc/ssh/ssh_host_ed25519_key"; }
      { type = "rsa"; bits = 3072; path = "/etc/ssh/ssh_host_rsa_key"; }
      { type = "ecdsa"; path = "/etc/ssh/ssh_host_ecdsa_key"; }
    ];
  };

  ###########################################################################
  # Provisioned TLS credentials: dnsdist runs as _dnsdist and must read the key.
  ###########################################################################

  environment.etc."node23/server.key" = {
    group = "_dnsdist";
    mode = lib.mkForce "0640";
  };

  ###########################################################################
  # Configuration files
  ###########################################################################

  environment.etc = {
    "dnsdist/dnsdist.conf" = {
      source = ./files/dnsdist/dnsdist.conf;
      user = "root";
      group = "_dnsdist";
      mode = "0640";
    };

    "nsd/nsd.conf".source = ./files/nsd/nsd.conf;
    "nsd/zones/a23.test.zone" = {
      source = ./files/nsd/zones/a23.test.zone;
      user = "root";
      group = "nsd";
      mode = "0640";
    };
    "nsd/zones/192.0.2.rev.zone" = {
      source = ./files/nsd/zones/192.0.2.rev.zone;
      user = "root";
      group = "nsd";
      mode = "0640";
    };

    "powerdns/recursor.conf".source = ./files/powerdns/recursor.conf;
    "powerdns/recursor.d/50-ttl.conf".source = ./files/powerdns/recursor.d/50-ttl.conf;
    "powerdns/recursor.d/60-legacy.conf.dpkg-old".source = ./files/powerdns/recursor.d/60-legacy.conf.dpkg-old;
    "powerdns/extrarecursorhosts".source = ./files/powerdns/extrarecursorhosts;
    "powerdns/zones/i23.test.zone".source = ./files/powerdns/zones/i23.test.zone;
  };

  ###########################################################################
  # Services
  ###########################################################################

  # Front door: UDP/TCP 53 and DNS-over-TLS 853, forwarding to the recursor.
  systemd.services.dnsdist = {
    description = "DNS Loadbalancer";
    documentation = [ "man:dnsdist(1)" "https://dnsdist.org" ];
    wants = [ "network-online.target" ];
    after = [ "network-online.target" ];
    wantedBy = [ "multi-user.target" ];
    startLimitIntervalSec = 0;
    serviceConfig = {
      ExecStartPre = "${dnsdist}/bin/dnsdist --check-config --config /etc/dnsdist/dnsdist.conf";
      ExecStart = "${dnsdist}/bin/dnsdist --supervised --disable-syslog --config /etc/dnsdist/dnsdist.conf";
      User = "_dnsdist";
      Group = "_dnsdist";
      Type = "notify";
      Restart = "on-failure";
