{ config, lib, pkgs, ... }:

let
  dnsdist = pkgs.dnsdist;
  recursor = pkgs.pdns-recursor;
  nsd = pkgs.nsd;

  recControl = "/run/current-system/sw/bin/rec_control";
in
{
  ###########################################################################
  # Identity
  ###########################################################################

  networking.hostName = "node23";
  networking.hosts."127.0.0.1" = [ "node23.n23.test" ];

  # The resolver is the local dnsdist listener; DHCP must not replace it.
  networking.nameservers = [ "127.0.0.1" ];
  networking.search = [ "n23.test" ];
  networking.dhcpcd.extraConfig = "nohook resolv.conf";

  time.timeZone = "Etc/UTC";
  i18n.defaultLocale = "C.UTF-8";

  # Ports served to clients: DNS over UDP/TCP, DNS over TLS, and SSH.
  networking.firewall = {
    enable = true;
    allowedTCPPorts = [ 22 53 853 ];
    allowedUDPPorts = [ 53 ];
  };

  boot.kernel.sysctl = {
    "net.core.rmem_max" = 8388608;
    "net.core.wmem_max" = 8388608;
    "net.ipv4.ip_local_port_range" = "10240 65535";
  };

  ###########################################################################
  # Accounts (names, UIDs/GIDs and home layout as provisioned)
  ###########################################################################

  users.groups = {
    admin = { gid = 117; };
    sudo = { gid = 27; };
    birch = { gid = 1301; };
    cedar = { gid = 1302; };
    nsd = { gid = 120; };
    pdns = { gid = 121; };
    _dnsdist = { gid = 122; };
  };

  users.users = {
    birch = {
      isNormalUser = true;
      uid = 1301;
      group = "birch";
      home = "/home/birch";
      homeMode = "750";
      createHome = true;
      description = "";
      shell = "/bin/bash";
      hashedPassword = "!";
    };

    cedar = {
      isNormalUser = true;
      uid = 1302;
      group = "cedar";
      home = "/home/cedar";
      homeMode = "750";
      createHome = true;
      description = "";
      shell = "/bin/bash";
      hashedPassword = "!";
    };

    nsd = {
      isSystemUser = true;
      uid = 112;
      group = "nsd";
      home = "/var/lib/nsd";
      createHome = false;
    };

    pdns = {
      isSystemUser = true;
      uid = 113;
      group = "pdns";
      description = "PowerDNS,,,";
      home = "/var/spool/powerdns";
      createHome = false;
    };

    _dnsdist = {
      isSystemUser = true;
      uid = 114;
      group = "_dnsdist";
      home = "/nonexistent";
      createHome = false;
    };
  };

