  ###########################################################################

  environment.etc = {
    "dnsdist/dnsdist.conf" = {
      source = ./files/dnsdist/dnsdist.conf;
      user = "root";
      group = "_dnsdist";
      mode = "0640";
    };

    "nsd/nsd.conf".source = ./files/nsd/nsd.conf;
    "nsd/zones/a23.test.zone" = {
      source = ./files/nsd/zones/a23.test.zone;
      user = "root";
      group = "nsd";
      mode = "0640";
    };
    "nsd/zones/192.0.2.rev.zone" = {
      source = ./files/nsd/zones/192.0.2.rev.zone;
      user = "root";
      group = "nsd";
      mode = "0640";
    };

    "powerdns/recursor.conf".source = ./files/powerdns/recursor.conf;
    "powerdns/recursor.d/50-ttl.conf".source = ./files/powerdns/recursor.d/50-ttl.conf;
    "powerdns/recursor.d/60-legacy.conf.dpkg-old".source = ./files/powerdns/recursor.d/60-legacy.conf.dpkg-old;
    "powerdns/extrarecursorhosts".source = ./files/powerdns/extrarecursorhosts;
    "powerdns/zones/i23.test.zone".source = ./files/powerdns/zones/i23.test.zone;
  };

